import { buildPracticeQuestion, type GraphChoicePlot, type QuestionInteractionConfig } from "./question-interactions.ts";
import type { CognitiveDemand, DepthQuestion, LessonDepthPack, QuestionEvidence } from "./curriculum-depth-types.ts";

const evidence = (objectiveId: string, demand: CognitiveDemand, representation: QuestionEvidence["representation"], misconception: string, difficulty: 1 | 2 | 3 = 2): QuestionEvidence => ({ objectiveId, demand, representation, difficulty, misconception, variantFamily: `${objectiveId}-pair-v2` });
type Response = { choices?: string[]; interactionConfig?: QuestionInteractionConfig };
const options = (...choices: string[]): Response => ({ choices });
const table = (columns: string[], rows: Array<[string, ...string[]]>): Response => ({ choices: rows.map(([value]) => value), interactionConfig: { kind: "table-choice", columns, rows: rows.map(([value, ...cells]) => ({ value, cells })) } });
const graph = (plots: GraphChoicePlot[], xMin: number, xMax: number, yMin: number, yMax: number): Response => ({ choices: plots.map((plot) => plot.value), interactionConfig: { kind: "graph-choice", plots, xMin, xMax, yMin, yMax } });
const q = (n: number, prompt: string, answer: string, hint: string, explanation: string, detail: QuestionEvidence, response: Response = {}): DepthQuestion => ({ ...buildPracticeQuestion({ id: `d2-q${n}`, prompt, answer, hint, ...response, interaction: response.interactionConfig?.kind }), evidence: detail, explanation });
const pack = (value: LessonDepthPack): LessonDepthPack => ({
  ...value,
  objectives: value.objectives.map((objective) => ({ ...objective, id: `${value.lessonSlug}:d2:${objective.id}` })),
  legacyObjectives: Object.fromEntries(Object.entries(value.legacyObjectives).map(([id, objective]) => [id, `${value.lessonSlug}:d2:${objective}`])),
  questions: value.questions.map((question) => ({ ...question, evidence: { ...question.evidence, objectiveId: `${value.lessonSlug}:d2:${question.evidence.objectiveId}`, variantFamily: `${value.lessonSlug}:d2:${question.evidence.variantFamily}` } })),
});

